const consent = { get: async () => ({ push: true }) };
const mk = (o = {}) => ({ id: "u" + Math.random(), timezone: "Europe/Istanbul", categories: { briefing: true }, snoozedUntil: null, platform: "ios", notificationsPermitted: true, ...o });
const run = (user, cand, now, c = consent, t = transport) => deliver({ user, candidate: cand, now, transport: t, consentStore: c });
const B = (id = "b1") => ({ id, type: "briefing" });
